  warn "Записал. До правки config.ts игра внутри Discord до сервера не достучится."
fi

# ── Stage 3: push + заливка env на VPS + деплой ────────────────────────────
stage "Деплой: push, env на VPS, пересборка"
say "Деплой делает git pull на VPS — сперва пушим main."
if [[ -n "$(git -C "$REPO_ROOT" status --porcelain)" ]]; then
  warn "В репо незакоммиченные изменения — deploy-all сам спросит, но лучше глянуть."
fi
ahead="$(git -C "$REPO_ROOT" rev-list '@{upstream}..HEAD' --count 2>/dev/null || echo '?')"
if [[ "$ahead" != "0" ]]; then
  say "Локальный main впереди origin на $ahead коммит(ов)."
  if confirm "Запушить сейчас (git push)?"; then
    git -C "$REPO_ROOT" push
    say "${GREEN}✓ запушено.${RESET}"
  else
    SKIPPED+=("git push не сделан — деплой подтянет старый код")
  fi
else
  say "${GREEN}✓ origin уже в курсе.${RESET}"
fi
say ""
say "Заливаю три ключа в /opt/wheee/deploy/.env на VPS (upsert, ничего не трёт):"
say "    DISCORD_CLIENT_ID, DISCORD_CLIENT_SECRET, VITE_DISCORD_CLIENT_ID (= Client ID)"
if confirm "Залить на $VPS?"; then
  ssh "$VPS" bash -s -- "$DISCORD_CLIENT_ID" "$DISCORD_CLIENT_SECRET" <<'REMOTE'
set -euo pipefail
f=/opt/wheee/deploy/.env
cid="$1"; secret="$2"
upsert() { sed -i "/^$1=/d" "$f"; printf '%s=%s\n' "$1" "$2" >> "$f"; }
upsert DISCORD_CLIENT_ID "$cid"
upsert DISCORD_CLIENT_SECRET "$secret"
upsert VITE_DISCORD_CLIENT_ID "$cid"
echo "ok: $(grep -c '^\(VITE_\)\?DISCORD_' "$f") discord-строк в $f"
REMOTE
  say "${GREEN}✓ env на VPS обновлён.${RESET}"
else
  SKIPPED+=("env на VPS не залит — добавить три DISCORD-переменные в /opt/wheee/deploy/.env руками")
fi
say ""
step "Теперь В ДРУГОМ ТЕРМИНАЛЕ (скрипт интерактивный, спросит подтверждения):"
say "    cd $REPO_ROOT && bash deploy/deploy-all.sh --server"
note "Это sync-env + git pull + docker compose up -d --build: соберёт discord-бандл"
note "(VITE_DISCORD_CLIENT_ID уходит build-arg'ом) и поднимет nginx с хостом discord.wheee.io."
pause "Деплой отработал? Enter — проверяю, что хост отвечает."
code="$(curl -sk -o /dev/null -w '%{http_code}' "https://discord.wheee.io/" || echo 000)"
if [[ "$code" == "200" ]]; then
