  SKIPPED+=("discord.wheee.io не отдал 200 — разобраться с деплоем до стадии сертификата")
fi

# ── Stage 4: сертификат ────────────────────────────────────────────────────
stage "Сертификат: расширить на discord.wheee.io"
say "Все три домена делят один cert /etc/letsencrypt/live/ru.wheee.io/ — его надо"
say "расширить (--expand), не выпускать отдельный."
say ""
step "Зайдите на VPS:  ssh $VPS"
step "Сначала разведка — КАК выпущен текущий cert (webroot / standalone / хостовый certbot):"
say "    cd /opt/wheee/deploy && docker compose config | grep -A3 certbot"
say "    crontab -l | grep -i certbot ; history | grep -i certbot | tail"
say ""
step "Если webroot (стандарт для этого compose) — команда:"
say "    docker compose run --rm certbot certonly --webroot -w /var/www/certbot --expand \\"
