# ── Stage 6: RTT-гейт ──────────────────────────────────────────────────────
stage "RTT-гейт: прокси Discord vs напрямую"
say "Гейт перед дальнейшей полировкой: медиана RTT через прокси из ЕС должна быть < 150 мс."
say ""
step "Проще всего мерить в БРАУЗЕРНОМ Discord (discord.com): запустите Activity, F12 → Console."
step "Вставьте сниппет (меряет 40 пинг-понгов по игровому протоколу):"
say ""
say '    (async () => {'
say "      const url = location.origin.replace('https','wss') + '/gameapi/ws';"
say '      const ws = new WebSocket(url); await new Promise(r => ws.onopen = r);'
say '      const rtts = [];'
say '      for (let i = 0; i < 40; i++) {'
say '        const t = performance.now();'
say '        ws.send(JSON.stringify({type:"ping"}));'
say '        await new Promise(r => ws.onmessage = e => { if (JSON.parse(e.data).type === "pong") r(); });'
say '        rtts.push(performance.now() - t);'
say '      }'
say '      rtts.sort((a,b) => a-b); ws.close();'
say '      console.log("median RTT:", rtts[20].toFixed(1), "ms");'
say '    })()'
say ""
step "Для сравнения: тот же сниппет в обычной вкладке на https://wheee.io, заменив url на 'wss://api.wheee.io/ws'."
ask RTT_PROXY_MS "Медиана через прокси, мс:"
ask RTT_DIRECT_MS "Медиана напрямую, мс:"
write_env RTT_PROXY_MS "$RTT_PROXY_MS"
write_env RTT_DIRECT_MS "$RTT_DIRECT_MS"
if [[ "${RTT_PROXY_MS%%.*}" =~ ^[0-9]+$ ]] && (( ${RTT_PROXY_MS%%.*} < 150 )); then
  say "${GREEN}✓ гейт пройден (${RTT_PROXY_MS} мс < 150 мс) — полировка Discord-версии оправдана.${RESET}"
else
  warn "Гейт НЕ пройден (${RTT_PROXY_MS} мс). Полировку геймплея отложить, сначала латентность."
  SKIPPED+=("RTT через прокси ${RTT_PROXY_MS} мс ≥ 150 — обсудить с Claude (регион VPS/оверхед Cloudflare Workers)")
fi

